package app.masroufy.core

/** بنك النصايح الموثّقة — الجزء 1 من 3 (متولّد بـ`gen-tips.js`؛ شوف [VERIFIED_TIPS]). بيانات بس. */
internal val VERIFIED_TIPS_1: List<BankTip> = listOf(
    BankTip(
        "track-spending-first", "both", "none", TipGroup.START,
        sa = TipWords("اعرف أين يذهب راتبك وضع خطة تبدأ من يوم الراتب", "سجّل لمدة شهر كل ما تكسبه وتنفقه موزعًا على تصنيفات، ودوّن مواعيد استحقاق فواتيرك، ودوّن كذلك ما تملكه وما عليك لتعرف صافي ثروتك وحدّثه سنويًا. ثم ضع خطة شهرية بسيطة تبدأ من يوم الراتب ويبقى فيها دائمًا جزء ولو صغير للادخار، وتجنّب الالتزامات الشهرية الكبيرة كقسط سيارة باهظة.", "قبل الادخار لا بد من إيجاد المال الذي يُدَّخر؛ فسجل الإنفاق يكشف التسربات الصغيرة المتراكمة، وتقويم الفواتير يوضح سبب نقص السيولة قبل الراتب، وهذه الصورة الواضحة نقطة البداية لسداد الديون وبناء الأهداف."),
        eg = TipWords("اعرف فلوسك بتروح فين واعمل خطة من يوم المرتب", "لمدة شهر، اكتب كل اللي بيدخلك وبيخرج منك وقسّمه على تصنيفات، وعلّم مواعيد الفواتير. واكتب كمان اللي تملكه واللي عليك عشان تعرف صافي ثروتك، وحدّثه كل سنة. بعدها اعمل خطة شهرية بسيطة تبدأ من يوم المرتب ويفضل فيها دايمًا جزء ولو صغير للادخار، وابعد عن الالتزامات الشهرية الكبيرة زي قسط عربية غالية.", "قبل ما تحوّش لازم تلاقي فلوس تحوّشها. تسجيل الصرف بيكشف التسريبات الصغيرة اللي بتتجمع، وتقويم الفواتير بيوضح ليه الفلوس بتخلص قبل المرتب، والصورة الواضحة دي أول خطوة لسداد أي دين أو بناء أي هدف."),
        source = TipSource("هيئة الأوراق المالية الأمريكية (موقع توعية المستثمر) — اعرف وضعك المالي", "https://www.investor.gov/introduction-investing/investing-basics/save-and-invest/figure-out-your-finances", "2026-10-16"),
    ),
    BankTip(
        "emergency-fund-first", "both", "low", TipGroup.START,
        sa = TipWords("كوّن صندوق طوارئ قبل أي استثمار أو هدف كبير", "قبل استثمار أي مبلغ أو الادخار لأهداف كبرى كالزواج أو المسكن أو التعليم، خصّص صندوقًا للطوارئ في حساب مستقل يسهل الوصول إليه دون أن يغري بالإنفاق. حدّد هدفه بناءً على المصروفات المفاجئة التي واجهتها سابقًا، والمرجع الشائع نحو 3 إلى 6 أشهر من نفقاتك الأساسية، ويحتفظ بعض الناس بما يعادل دخل ستة أشهر. وإن كنت مغتربًا فاجعله يغطي الطوارئ في البلدين.", "دون احتياطي قد يدفعك فقدان العمل أو إصلاح السيارة أو فاتورة علاج إلى قرض أو بطاقة، أو إلى السحب من مدخرات أهدافك، أو إلى بيع استثمار في توقيت سيئ. وحتى الرصيد الصغير يوفر قدرًا من الحماية."),
        eg = TipWords("اعمل صندوق طوارئ قبل أي استثمار أو هدف كبير", "قبل ما تستثمر أو تحوّش لجواز أو شقة أو تعليم، جنّب فلوس طوارئ في حساب لوحده تقدر توصله بسرعة بس مش سهل تصرف منه. حدد هدف على حسب المفاجآت اللي حصلتلك قبل كده، والمرجع الشائع حوالي 3 لـ6 شهور من مصاريفك الأساسية، وفيه ناس بتوصل لدخل 6 شهور. ولو عايش بين بلدين، خلّيه يغطي المفاجآت هنا وهناك.", "من غير احتياطي، أي ظرف زي فقد الشغل أو تصليح العربية أو فاتورة علاج ممكن يزقك لقرض أو بطاقة، أو يخليك تكسر فلوس هدف، أو تبيع استثمار وهو نازل. حتى مبلغ صغير بيحميك شوية."),
        source = TipSource("مكتب الحماية المالية للمستهلك الأمريكي — الدليل الأساسي لبناء صندوق الطوارئ", "https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/", "2026-10-16"),
    ),
    BankTip(
        "emergency-fund-habit", "both", "none", TipGroup.START,
        sa = TipWords("ابدأ صندوق الطوارئ صغيرًا واجعل التحويل إليه تلقائيًا", "في كل يوم راتب، حوّل مبلغًا صغيرًا ثابتًا إلى حساب الطوارئ قبل أن تبدأ الإنفاق، حتى أثناء سداد الديون، كي لا ينتهي إصلاح سيارة أو فاتورة علاج على البطاقة. وأضف إليه الدخل غير المتكرر كالمكافآت والهدايا وفائض الأشهر التي يزيد فيها دخلك على المعتاد. وحدّد مسبقًا ما يُعد طارئًا حقيقيًا، وإذا استخدمت الصندوق فأعد تعبئته قبل العودة إلى أهدافك الأخرى.", "المبالغ الصغيرة المنتظمة تبني العادة، ودون احتياطي يتحول كل مصروف مفاجئ إلى دين جديد فلا تنتهي الدائرة. ومع الدخل غير المنتظم تكون الأشهر الجيدة أنسب وقت لبناء الصندوق. ويمكن في التطبيق جعل الصندوق محفظة مستقلة."),
        eg = TipWords("ابدأ صندوق الطوارئ صغير وخلّي التحويل تلقائي", "يوم القبض، حوّل مبلغ صغير ثابت لحساب الطوارئ قبل ما تبدأ تصرف، حتى وانت بتسدّد ديون، عشان تصليح عربية أو فاتورة دكتور ما تروحش على البطاقة. زوّد عليه أي فلوس زيادة زي المكافآت والهدايا والشهور اللي دخلك فيها أعلى من العادي. حدد من الأول إيه اللي يعتبر طوارئ بجد، ولو سحبت منه رجّعه زي ما كان قبل ما تكمل في أهداف تانية.", "المبالغ الصغيرة المنتظمة بتعمل عادة، ومن غير احتياطي أي مصروف مفاجئ بيبقى دين جديد والدايرة ما بتخلصش. ولما دخلك متقطع، الشهور الحلوة أسهل وقت تبني فيه الصندوق. وفي التطبيق ممكن الصندوق يبقى محفظة لوحدها."),
        source = TipSource("مكتب الحماية المالية للمستهلك الأمريكي — دليل بناء صندوق الطوارئ", "https://www.consumerfinance.gov/an-essential-guide-to-building-an-emergency-fund/", "2026-10-16"),
    ),
    BankTip(
        "emergency-money-no-riba", "both", "low", TipGroup.HALAL,
        sa = TipWords("أين تحفظ مال الطوارئ بعيدًا عن الربا", "ينبغي أن يكون مال الطوارئ آمنًا ومتاحًا فورًا. فالحساب الجاري لا يدرّ فائدة ويمكن السحب منه في أي وقت، أما الوديعة الاستثمارية المتوافقة مع الشريعة (المضاربة) فقد تحقق ربحًا لكن رأس مالها غير مضمون، فهي أنسب لمال لا تحتاجه قريبًا.", "يساعدك على اختيار المكان المناسب لكل جزء من مدخراتك: سيولة فورية للطوارئ، ومنتجات المشاركة في الربح للأموال طويلة الأجل فقط."),
        eg = TipWords("تحط فلوس الطوارئ فين من غير ربا؟", "فلوس الطوارئ لازم تبقى في أمان وتقدر تسحبها في أي وقت. الحساب الجاري ما بيطلعش فوايد وتسحب منه وقت ما تحب. أما الوديعة الاستثمارية المتوافقة مع الشريعة (مضاربة) ممكن تطلع ربح، بس رأس مالها مش مضمون، فتناسب فلوس مش هتحتاجها قريب.", "بيساعدك تختار المكان الصح لكل جزء من مدخراتك: سحب سريع للطوارئ، والمنتجات اللي بتقسم الربح للفلوس الطويلة بس."),
        source = TipSource("مجمع الفقه الإسلامي الدولي — القرار رقم 86 (3/9) بشأن الودائع المصرفية", "https://iifa-aifi.org/en/32511.html", "2026-10-16"),
    ),
    BankTip(
        "pay-yourself-first", "both", "none", TipGroup.START,
        sa = TipWords("ادفع لنفسك أولًا: عامل نسبة الادخار كفاتورة ثابتة", "اقتطع حصة الادخار (مثلًا 10%) يوم صرف الراتب كما تدفع الإيجار، بدلًا من ادخار ما يتبقى آخر الشهر. دوّن دخلك ومصروفاتك الشهرية مع بند مخصص للادخار، وابحث عن المشتريات الصغيرة المتكررة التي يمكن تقليصها، وتمهّل يومًا قبل أي شراء اندفاعي.", "حين يأتي الادخار أولًا وتلقائيًا تتحقق نسبة 10% كل شهر، لا في الأشهر الميسورة وحدها."),
        eg = TipWords("ادفع لنفسك الأول: الـ10% زي الإيجار", "يوم القبض، حوّل نصيب التوفير (مثلًا 10%) الأول زي ما بتدفع الإيجار، بدل ما تستنى اللي يفضل آخر الشهر. اكتب دخلك ومصاريفك الشهرية وحط فيها بند للتوفير، ودوّر على المشتريات الصغيرة المتكررة اللي ممكن تقللها. ولو حاجة شدّتك فجأة، استنى يوم قبل ما تشتريها.", "لما التوفير يبقى الأول وتلقائي، الـ10% بتتحوّش كل شهر، مش في الشهور الحلوة بس."),
        source = TipSource("هيئة الأوراق المالية والبورصات الأمريكية — خريطة الادخار والاستثمار: ضع خطة مالية", "https://www.sec.gov/investor/pubs/roadmap/habit.htm", "2026-10-16"),
    ),
    BankTip(
        "saudi-savings-target-10", "sa", "none", TipGroup.START,
        sa = TipWords("نسبة 10% هدف وطني للادخار في المملكة", "تستهدف استراتيجية الادخار الوطنية في المملكة رفع نسبة ادخار الأسر من دخلها من نحو 6% إلى 10% بحلول عام 2030، وادخار 10% من دخلك شهريًا يتوافق مع هذا الهدف.", "يمنح نسبة 10% الافتراضية مرجعًا رسميًا، فلا تبدو رقمًا اعتباطيًا."),
        eg = TipWords("الـ10% هي هدف السعودية للادخار", "استراتيجية الادخار الوطنية في السعودية هدفها ترفع نسبة اللي الأسر بتحوّشه من دخلها من حوالي 6% لـ10% بحلول 2030. لو بتحوّش 10% من دخلك كل شهر، تبقى ماشي مع الهدف ده.", "بيدّي رقم الـ10% مرجع رسمي بدل ما يبان رقم عشوائي."),
        source = TipSource("هيئة السوق المالية — خبر منتدى برنامج تطوير القطاع المالي (مايو 2018)", "https://cma.gov.sa/en/MediaCenter/PR/Pages/FSDP.aspx", "2026-10-16"),
    ),
    BankTip(
        "financing-cap-is-ceiling", "sa", "medium", TipGroup.DEBT,
        sa = TipWords("حدود التمويل من الراتب سقف أعلى لا هدف", "اجمع أقساطك الشهرية كلها (تمويل شخصي، سيارة، بطاقة، مسكن) وقارن مجموعها بإجمالي راتبك. تضع قواعد البنك المركزي السعودي سقفًا للأقساط المستقطعة من الراتب: ثلث الراتب الإجمالي للموظف وربعه للمتقاعد، ويُحتسب ضمنه الحد الأدنى لسداد البطاقات، كما تضع سقفًا لإجمالي الالتزامات الشهرية يختلف بحسب الدخل ويرتفع قليلًا عند وجود تمويل سكني. تعامل مع هذه الحدود بوصفها حدًا أقصى لا ميزانية، وأبقِ أقساطك دونها بوضوح، وإن اقتربت منها فتجنّب أي تمويل جديد.", "كل ريال مقيد بأقساط لسنوات لا يذهب إلى صندوق الطوارئ أو الادخار أو أهداف الأسرة، ويقلل ما يمكن الحصول عليه من تمويل سكني لاحقًا. وقد يوافق الممول حتى الحد النظامي الأقصى، فبلوغه لا يعني أن القسط مريح."),
        eg = TipWords("حدود التمويل من المرتب سقف مش هدف", "اجمع كل أقساطك الشهرية (تمويل شخصي، عربية، بطاقة، بيت) وقارنها بإجمالي مرتبك. قواعد البنك المركزي السعودي بتحط سقف للأقساط اللي بتتخصم من المرتب: ثلث الراتب الإجمالي للموظف وربعه للمتقاعد، والحد الأدنى لسداد البطاقات داخل فيه. وفيه كمان سقف لإجمالي الالتزامات الشهرية بيختلف حسب الدخل، وأعلى شوية لو فيه تمويل سكني. اعتبر الحدود دي أقصى حاجة مش ميزانية، وخلّي أقساطك أقل منها بكتير، ولو قربت منها بلاش تمويل جديد.", "كل ريال محبوس في أقساط لسنين مش هيروح لصندوق الطوارئ ولا للتحويش ولا لأهداف العيلة، وبيقلل التمويل اللي ممكن تاخده للبيت بعدين. والجهة الممولة ممكن توافقلك لحد الحد القانوني، فالوصول ليه مش معناه إن القسط مريح."),
        source = TipSource("البنك المركزي السعودي — دليل القواعد: مبادئ الإقراض المسؤول للأفراد، الفصل الرابع (المبادئ الكمية)", "https://rulebook.sama.gov.sa/en/chapter-iv-quantitative-principles-responsible-lending", "2026-10-16"),
    ),
    BankTip(
        "never-share-bank-codes", "both", "high", TipGroup.PROTECT,
        sa = TipWords("لا تشارك رقمك السري أو رمز التحقق مع أحد", "لا تُطلع أحدًا على رقم بطاقتك أو حسابك أو رقمك السري أو كلمة المرور أو رمز التحقق المؤقت، ممن يتصل بك أو يراسلك أو يرسل لك رابطًا، ولو ادّعى أنه من بنكك أو من البنك المركزي أو جهة حكومية أو أن هناك أموالًا بانتظارك. فالبنك لا يطلب منك الرقم السري أو كلمة المرور أو رمز التحقق، والبنك المركزي لا يحتفظ بأموال الأفراد. وإن طُلبت منك أو فُقدت أموال أو بطاقة فتواصل مع بنكك فورًا عبر رقمه الرسمي.", "ينتحل المحتالون صفة جهات رسمية للحصول على الرموز ثم يفرغون الحسابات أو يفتحون تمويلًا باسمك. وحامل الراتب الأول والمدخر لمبلغ كبير والمدين أصلًا أهداف شائعة لهم، ورمز واحد قد يُضيّع مدخرات سنوات، والتحرك السريع يمنح البنك فرصة لإيقاف الخسارة."),
        eg = TipWords("ما تديش الرقم السري ولا رمز التحقق لأي حد", "ما تديش رقم بطاقتك ولا حسابك ولا الرقم السري ولا كلمة السر ولا رمز التحقق اللي بيوصلك في رسالة لأي حد بيتصل بيك أو يبعتلك رسالة أو رابط، حتى لو قال إنه من بنكك أو من البنك المركزي أو جهة حكومية أو إن فيه فلوس مستنياك. البنك عمره ما يطلب منك الرقم السري ولا كلمة السر ولا رمز التحقق، والبنك المركزي ما بيمسكش فلوس الأفراد. ولو حد طلبهم أو فلوس اختفت أو البطاقة ضاعت، كلّم بنكك فورًا من رقمه الرسمي.", "النصابين بيتقمصوا جهات رسمية عشان ياخدوا الرموز ويفضّوا الحساب أو يفتحوا تمويل باسمك. صاحب أول مرتب واللي محوّش مبلغ كبير واللي عليه ديون أصلًا أهداف مفضلة ليهم، ورمز واحد ممكن يضيّع تحويشة سنين، والتحرك بسرعة بيدي البنك فرصة يوقف الخسارة."),
        source = TipSource("البنك المركزي السعودي — خبر الإجراءات الاحترازية لمكافحة الاحتيال (8 أبريل 2022)", "https://www.sama.gov.sa/ar-sa/MediaCenter/News/Pages/news-752.aspx", "2026-10-16"),
    ),
    BankTip(
        "fraud-signs-sa", "sa", "high", TipGroup.PROTECT,
        sa = TipWords("في المملكة: تحقق من الترخيص واعرف علامات الاحتيال", "احذر ممن يعد بعائد مضمون أو مرتفع جدًا في مدة قصيرة، أو يستعجلك في القرار، أو يعجز عن شرح مصدر الربح، أو يطلب التحويل إلى حساب شخصي، ولا سيما عبر وسائل التواصل وتطبيقات المراسلة أو في إعلانات مصممة كالأخبار تزعم طرح استثمار حكومي. وقبل تسليم مالك لوسيط أو مدير صندوق أو مستشار، تحقق بنفسك عبر الموقع الرسمي من وروده في قائمة المرخص لهم لدى هيئة السوق المالية أو البنك المركزي لذلك النشاط تحديدًا، فإن لم يكن مدرجًا فلا تتعامل معه وأبلغ عنه.", "العروض غير المرخصة من أكثر الطرق التي تضيع بها المدخرات، من المدخرات الأولى إلى مكافأة نهاية الخدمة. والعقود مع غير المرخص لهم باطلة وحمايتها ضعيفة، والأموال المحوّلة يصعب استردادها."),
        eg = TipWords("في السعودية: اتأكد من الترخيص واعرف علامات النصب", "اشك في أي حد يوعدك بربح مضمون أو عالي جدًا في وقت قصير، أو يزنّ عليك تقرر حالًا، أو مش عارف يشرح الربح جاي منين، أو يطلب تحوّل على حساب شخصي، وخصوصًا لو جالك على مواقع التواصل أو الواتساب أو في إعلان شكله خبر بيدّعي إنه استثمار حكومي. قبل ما تدّي فلوس لوسيط أو مدير صندوق أو مستشار، اتأكد بنفسك من الموقع الرسمي إنه في قايمة المرخّص لهم عند هيئة السوق المالية أو البنك المركزي للنشاط ده بالظبط. مش موجود؟ ما تتعاملش معاه وبلّغ عنه.", "العروض غير المرخّصة من أشهر الطرق اللي الناس بتخسر بيها تحويشتها، من أول تحويشة لحد مكافأة نهاية الخدمة. والعقود مع غير المرخّص باطلة وحمايتها ضعيفة، والفلوس اللي بتتبعت صعب ترجع."),
        source = TipSource("هيئة السوق المالية — تجنب التعامل مع غير المرخص لهم في أعمال الأوراق المالية", "https://cma.gov.sa/en/MediaCenter/PR/Pages/Avoid-Dealing-with-Unauthorized-Persons.aspx", "2026-10-16"),
    ),
    BankTip(
        "fraud-signs-eg", "eg", "high", TipGroup.PROTECT,
        sa = TipWords("في مصر: راجع سجل الرقابة المالية وقائمتها السلبية قبل أي استثمار", "قبل تسليم أموالك لأي شركة أو منصة تداول أو صفحة «إدارة أموال» أو تطبيق يعرض الاستثمار أو التمويل أو تنمية مدخرات الزواج أو استثمارها في العقار، تحقق من موقع الهيئة العامة للرقابة المالية أنه مدرج في سجل المرخص لهم وغير وارد في القائمة السلبية. والعوائد الكبيرة أو السريعة أو المضمونة، والأرباح الصغيرة في البداية لكسب الثقة، والطلب منك ضم آخرين، كلها علامات خطر. ولا تشارك بياناتك المصرفية أو رمز التحقق أبدًا، وأبلغ عن العروض المريبة عبر الخط الساخن 19669.", "قد تستولي المنصات غير المرخصة على المال كله وعلى بياناتك دون جهة رقابية تلجأ إليها. وتستهدف خصوصًا أصحاب مكافآت نهاية الخدمة ومدخرات الزواج والمسكن والشباب، والمغترب الذي تصله العروض عبر الأقارب دون قدرة على التحقق بنفسه."),
        eg = TipWords("في مصر: شوف سجل الرقابة المالية والقايمة السلبية قبل أي استثمار", "قبل ما تدّي فلوسك لأي شركة أو منصة تداول أو صفحة «إدارة أموال» أو تطبيق بيعرض استثمار أو تمويل أو يكبّر تحويشة الجواز أو يشغّلها في عقار، ادخل موقع الهيئة العامة للرقابة المالية واتأكد إنه في سجل المرخّصين ومش في القايمة السلبية. المكسب الكبير أو السريع أو المضمون، والأرباح الصغيرة في الأول عشان تثق، وطلب إنك تجيب صحابك، كلها علامات خطر. عمرك ما تدّي بيانات بنكك أو رمز التحقق، وبلّغ عن أي عرض مريب على الخط الساخن 19669.", "المنصات غير المرخّصة ممكن تاخد الفلوس كلها وبياناتك كمان، ومش هتلاقي جهة رقابية ترجعلها. وبتستهدف بالذات اللي معاهم مكافأة نهاية خدمة أو فلوس جواز وشقة، والشباب، واللي عايش برّه وبيوصله العرض من قرايب ومش قادر يتأكد بنفسه."),
        source = TipSource("الهيئة العامة للرقابة المالية (مصر) — تحذير من المنصات غير المرخّصة التي تعد بأرباح غير واقعية (8 مايو 2026)", "https://fra.gov.eg/en/fra_news/%D8%A7%D8%AD%D8%B0%D8%B1-%D9%85%D9%86-%D8%A7%D9%84%D9%86%D8%B5%D8%A8-%D8%A8%D8%AF%D8%B9%D9%88%D9%89-%D8%AA%D8%AD%D9%82%D9%8A%D9%82-%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%AE%D9%8A%D8%A7%D9%84%D9%8A%D8%A9/", "2026-10-16"),
    ),
    BankTip(
        "check-license-finance-offers", "both", "high", TipGroup.PROTECT,
        sa = TipWords("عروض سداد القروض والتمويل السريع: تحقق من الترخيص أولًا", "يتلقى المدينون ومن يخشون الغلاء عروضًا مثل «نسدّد قروضك» أو تمويل سريع أو ربح مضمون أو «سلّمني أموالك لأستثمرها»، غالبًا عبر تطبيقات المراسلة ومواقع التواصل، أو من شخص يجمع الأموال من الأقارب والأصدقاء. قبل التعامل مع أي جهة، تحقق من وجودها في قائمة الجهات المرخصة: البنك المركزي السعودي في المملكة، والهيئة العامة للرقابة المالية في مصر. العروض غير الواقعية، والضغط لاتخاذ قرار سريع، والأسماء المشابهة للبنوك الحقيقية علامات خطر، ولا حماية رقابية مع الجهات غير المرخصة.", "كثيرًا ما تضيف الجهات غير المرخصة هوامش مرتفعة خفية أو تسرق البيانات فتزيد الدين، وجمع الأموال دون ترخيص من أشهر طرق ضياع المدخرات."),
        eg = TipWords("عروض «نسدّد قروضك» والتمويل السريع: اتأكد من الترخيص الأول", "اللي عليهم ديون واللي خايفين من الغلا بتوصلهم عروض زي «نسدّد قروضك» أو تمويل سريع أو ربح مضمون أو «هات فلوسك أشغّلهالك»، غالبًا على تطبيقات المراسلة ومواقع التواصل، أو من شخص بيلم فلوس من الأهل والصحاب. قبل ما تتعامل مع أي حد، اتأكد إنه موجود في قائمة الجهات المرخصة: البنك المركزي السعودي في السعودية، والهيئة العامة للرقابة المالية في مصر. العروض اللي مش منطقية، والضغط عشان تقرر بسرعة، والأسامي اللي شبه البنوك الحقيقية، علامات خطر، والجهة غير المرخصة ما معاهاش أي حماية رقابية.", "الجهات غير المرخصة كتير بتحط هوامش عالية مستخبية أو بتسرق البيانات فتزوّد الدين، وتجميع الفلوس من غير ترخيص من أشهر طرق ضياع المدخرات."),
        source = TipSource("البنك المركزي السعودي — ما الأنشطة غير المرخصة؟", "https://www.sama.gov.sa/en-US/Supervision/Pages/unlicensed_activities.aspx", "2026-10-16"),
    ),
    BankTip(
        "check-social-insurance", "sa", "low", TipGroup.START,
        sa = TipWords("تحقق من تسجيلك وأجرك في التأمينات الاجتماعية من أول وظيفة", "منذ التحاقك بالعمل في القطاع الخاص، لا عند التقاعد، اطّلع على سجلك لدى المؤسسة العامة للتأمينات الاجتماعية عبر خدماتها الإلكترونية، وتأكد من أن صاحب العمل سجّلك فعلًا، ومن أن الأجر المسجل يطابق راتبك الأساسي الفعلي مع بدل السكن، وإن وجدت خطأ فارفعه إلى المؤسسة.", "يُحسب المعاش والمنافع الأخرى من الأجور المسجلة وعدد أشهر الاشتراك، وتسجيل أجر أقل من الحقيقي يُنقصها بصمت لسنوات، وتصحيح الأخطاء أيسر ما دامت السجلات حديثة."),
        eg = TipWords("راجع تسجيلك وأجرك في التأمينات من أول شغل", "من أول ما تشتغل في القطاع الخاص، مش وقت المعاش، بص على سجلك في المؤسسة العامة للتأمينات الاجتماعية من خدماتها الإلكترونية. اتأكد إن صاحب الشغل سجّلك فعلًا، وإن الأجر المكتوب ليك هو أساسي مرتبك الحقيقي مع بدل السكن. لو فيه غلط، اعترض عند المؤسسة.", "المعاش ومزايا تانية بيتحسبوا من الأجور المسجلة وعدد شهور الاشتراك، والأجر المتسجّل أقل من الحقيقي بيقلل معاشك في صمت لسنين، والغلط أسهل يتصلح وهو لسه جديد."),
        source = TipSource("المؤسسة العامة للتأمينات الاجتماعية: دعوة موظفي القطاع الخاص للتحقق من تسجيلهم (16 يوليو 2019)", "https://www.gosi.gov.sa/GOSIOnline/_news34en&locale=en_US", "2026-10-16"),
    ),
    BankTip(
        "zakaty-calculator-sa", "sa", "none", TipGroup.HALAL,
        sa = TipWords("تابع زكاة مدخراتك عبر منصة «زكاتي» الرسمية", "مع نمو مدخراتك، ولو كانت مخصصة للمسكن، تابع بلوغها النصاب ومرور حول هجري كامل عليها. وتتيح منصة «زكاتي» من هيئة الزكاة والضريبة والجمارك، تطبيقًا وموقعًا، حساب زكاة النقد والذهب والفضة والأسهم والصناديق والعقار مجانًا في مكان واحد، مع جلب أسعار الأسهم والصناديق عبر الربط مع «تداول» والتذكير بموعد الاستحقاق، والدفع من خلالها اختياري. سجّل تاريخ بلوغ كل وعاء ادخاري النصاب لأول مرة.", "توزع المدخرات بين حسابات وذهب واستثمارات، أو امتدادها لسنوات، يجعل الزكاة عرضة للخطأ أو النسيان، والتطبيق يعرف الرصيد وتاريخ بلوغه."),
        eg = TipWords("تابع زكاة تحويشتك بمنصة «زكاتي» الرسمية", "مع زيادة تحويشتك، حتى لو محوّشها للبيت، تابع إمتى توصل للنصاب وإمتى يعدّي عليها سنة هجرية كاملة. منصة «زكاتي» من هيئة الزكاة والضريبة والجمارك، تطبيق وموقع، بتحسب مجانًا زكاة الكاش والدهب والفضة والأسهم والصناديق والعقار في مكان واحد، وبتجيب أسعار الأسهم والصناديق من «تداول» وبتفكّرك بالميعاد، والدفع من خلالها اختياري. سجّل التاريخ اللي كل تحويشة وصلت فيه النصاب أول مرة.", "لما التحويشة تبقى متفرقة بين حسابات ودهب واستثمارات، أو بتقعد سنين، سهل تغلط في الزكاة أو تنساها. والتطبيق عارف الرصيد وتاريخ وصوله."),
        source = TipSource("هيئة الزكاة والضريبة والجمارك — منصة «زكاتي» لحساب الزكاة وأدائها", "https://zatca.gov.sa/ar/MediaCenter/News/Pages/ZAKATY2026.aspx", "2026-10-16"),
    ),
    BankTip(
        "zakat-savings-nisab-date", "both", "none", TipGroup.HALAL,
        sa = TipWords("سجّل تاريخ بلوغ مدخراتك النصاب", "تجب الزكاة في المدخرات النقدية إذا بلغت النصاب فاضلة عن الحاجات الأصلية وحال عليها حول هجري كامل، ومقدارها 2.5%، أي المبلغ مقسومًا على 40. ونصاب النقود وفق دليل هيئة الزكاة والضريبة والجمارك هو الأقل من قيمة 85 غرامًا من الذهب أو 595 غرامًا من الفضة، وغالبًا ما تكون الفضة هي الأقل. سجّل تاريخ بلوغ مدخراتك النصاب أول مرة، ولا سيما إن كان دخلك غير منتظم ومدخراتك تعلو وتنخفض. وإن كنت تدخر من راتب شهري فيجوز لك تحديد موعد سنوي واحد وإخراج زكاة مدخراتك كلها دفعة واحدة.", "يظن كثيرون أن الزكاة على الأغنياء وحدهم، مع أن مدخرات متواضعة قد تتجاوز نصاب الفضة، والادخار غير المنتظم يجعل من السهل أن يغيب عنك موعد الزكاة ومقدارها."),
        eg = TipWords("سجّل إمتى مدخراتك وصلت النصاب", "الزكاة بتجب على المدخرات الكاش اللي توصل النصاب زيادة عن احتياجاتك الأساسية لما يعدّي عليها سنة هجرية كاملة، ومقدارها 2.5%، يعني المبلغ مقسوم على 40. ونصاب الفلوس حسب دليل هيئة الزكاة والضريبة والجمارك هو الأقل بين قيمة 85 جرام دهب و595 جرام فضة، وغالبًا الفضة هي الأقل. سجّل التاريخ اللي مدخراتك وصلت فيه النصاب أول مرة، خصوصًا لو دخلك متقطع ومدخراتك بتطلع وتنزل. ولو بتحوّش من مرتب شهري، تقدر تحدد يوم واحد في السنة وتزكّي عن كله مرة واحدة.", "ناس كتير فاكرين إن الزكاة على الأغنيا بس، مع إن مدخرات بسيطة ممكن تعدّي نصاب الفضة. والادخار المتقطع بيخلّي سهل تتوه عن ميعاد الزكاة ومقدارها."),
        source = TipSource("هيئة الزكاة والضريبة والجمارك: دليل فقه زكاة الأفراد", "https://www.zatca.gov.sa/en/HelpCenter/guidelines/Documents/ZakatJurisIndivisuals.pdf", "2026-10-16"),
    ),
    BankTip(
        "match-money-to-horizon", "both", "low", TipGroup.START,
        sa = TipWords("وائم مكان المال مع موعد الهدف", "لكل هدف موعد، والموعد يحدد مكان ماله. فالمال الذي تحتاجه خلال سنوات قليلة، كالدفعة الأولى للمسكن أو الزواج أو السيارة، مكانه الخيارات منخفضة المخاطر سهلة التسييل، أما المخاطرة الأعلى فتقتصر على الأهداف البعيدة. وكلما اقترب موعد الهدف، ومن أهمها التقاعد، فانقل ماله تدريجيًا إلى أماكن أكثر استقرارًا، وراجع التوزيع مرة أو مرتين سنويًا أو كلما تغيرت ظروفك.", "هبوط السوق قبيل موعد الزواج أو الرسوم الجامعية أو التقاعد قد يضطرك إلى البيع بخسارة أو تأجيل الهدف دون وقت كافٍ للتعويض."),
        eg = TipWords("خلّي مكان الفلوس على قد ميعاد الهدف", "لكل هدف ميعاد، والميعاد بيحدد مكان فلوسه. الفلوس اللي محتاجها خلال كام سنة، زي مقدم الشقة أو الجواز أو العربية، مكانها حاجات قليلة المخاطرة وسهل تسيّلها، والمخاطرة الأعلى للأهداف البعيدة بس. وكل ما ميعاد الهدف يقرب، وأهمها التقاعد، انقل فلوسه خطوة خطوة لأماكن أهدى، وراجع التوزيع مرة أو مرتين في السنة أو لما ظروفك تتغير.", "لو السوق وقع قبل ميعاد الجواز أو مصاريف الجامعة أو التقاعد على طول، ممكن تضطر تبيع بخسارة أو تأجل الهدف، ومفيش وقت كفاية تعوّض."),
        source = TipSource("هيئة السوق المالية — أساسيات الاستثمار: التخطيط المالي", "https://cma.gov.sa/en/Awareness/InvestmentBasics/Pages/FinancialPlanning.aspx", "2026-10-16"),
    ),
    BankTip(
        "sah-savings-sukuk", "sa", "low", TipGroup.START,
        sa = TipWords("صكوك «صح» الحكومية: للادخار المنتظم لا للطوارئ", "بعد اكتمال صندوق الطوارئ، من المفيد التعرف على «صح»، وهي صكوك ادخار حكومية متوافقة مع الشريعة للمواطنين من سن 18. تُطرح شهريًا، ومدة كل إصدار سنة بعائد يُحدَّد عند طرحه، من 1,000 إلى 200,000 ريال للفرد دون رسوم، وتُشترى عبر جهات مرخصة. ولا يُسترد المبلغ مبكرًا إلا في مواعيد محددة مع فقد الربح المتراكم، ولا تُتداول في السوق، فلا تناسب مالًا قد تحتاجه فجأة. راجع الشروط في الصفحة الرسمية قبل الاكتتاب. هذه معلومة عامة لا توصية.", "يترك كثير من المتحرّزين من الربا أموالهم معطلة، ومعرفة البدائل الرسمية منخفضة المخاطر تعين على الادخار المنتظم للأهداف البعيدة، ومعرفة شرط الاسترداد المبكر تجنّب المفاجآت، ولا سيما للمقبلين على التقاعد."),
        eg = TipWords("صكوك «صح» الحكومية: للتوفير الطويل، مش للطوارئ", "بعد ما صندوق الطوارئ يكمل، كويس تعرف «صح»: صكوك ادخار حكومية متوافقة مع الشريعة للمواطنين السعوديين من 18 سنة. بتنزل كل شهر، ومدة كل إصدار سنة بعائد بيتحدد وقت الإصدار، من 1,000 لحد 200,000 ريال للشخص ومن غير رسوم، وبتتشترى عن طريق جهات مرخّصة. السحب بدري في مواعيد محددة بس وبيضيّع الربح المتراكم، والصكوك ما بتتباعش في السوق، فمش مناسبة لفلوس ممكن تحتاجها فجأة. اقرا الشروط من الصفحة الرسمية قبل ما تشترك. دي معلومة عامة مش توصية.", "ناس كتير بتسيب فلوسها نايمة عشان بتتجنب الفايدة، ومعرفة البدايل الرسمية قليلة المخاطرة بتساعد على التحويش المنتظم لأهداف بعيدة. ومعرفة شرط السحب بدري بتمنع المفاجآت، خصوصًا للي قرّب على التقاعد."),
        source = TipSource("المركز الوطني لإدارة الدين — صكوك «صح» الادخارية", "https://sukuk.ndmc.gov.sa/en/", "2026-10-16"),
    ),
    BankTip(
        "home-down-payment", "sa", "low", TipGroup.START,
        sa = TipWords("خطط لدفعة أولى لا تقل عن 10% إضافة إلى الرسوم", "في المسكن الأول للمواطن تسمح الأنظمة السعودية بتمويل 90% كحد أقصى من قيمة العقار، فخطط لادخار 10% على الأقل من السعر، إضافة إلى الرسوم والتأثيث والانتقال.", "تحسب أسر كثيرة القسط الشهري فقط فتفاجأ بالسيولة المطلوبة مقدمًا، وتحديد هدف للدفعة الأولى يحوّل الادخار للمسكن إلى مبلغ شهري يتابعه التطبيق. ويستحسن التحقق من الأهلية للدعم السكني لأنه قد يغيّر الحساب."),
        eg = TipWords("جهّز مقدم 10% على الأقل غير المصاريف", "في أول بيت للمواطن، القواعد السعودية بتسمح للجهة الممولة تمول لحد 90% بس من قيمة العقار، يعني لازم تحوّش 10% على الأقل من السعر، وزيادة عليها للرسوم والفرش والنقل.", "عائلات كتير بتحسب القسط الشهري بس وتتفاجئ بالكاش المطلوب في الأول. هدف المقدم الواضح بيحوّل «بحوّش لبيت» لرقم شهري التطبيق يتابعه. وراجع أهليتك للدعم السكني لأنه ممكن يغيّر الحسبة."),
        source = TipSource("البنك المركزي السعودي — تعميم رفع الحد الأقصى للتمويل العقاري لتملك المواطنين المسكن الأول", "https://rulebook.sama.gov.sa/en/entiresection/6106", "2026-10-16"),
