    BankTip(
        "clear-costly-debt-first", "both", "low", TipGroup.DEBT,
        sa = TipWords("سدّد الديون المرتفعة التكلفة قبل الاستثمار", "قبل وضع أي مبلغ في استثمار، سدّد الديون المرتفعة التكلفة، وفي مقدمتها رصيد البطاقة الائتمانية وخطط التقسيط المكلفة. التزم بالحد الأدنى على كل دين، ووجّه أي مبلغ إضافي إلى الدين الأعلى تكلفة. ومن الآن فصاعدًا لا تستخدم البطاقة الائتمانية إلا إذا كان لديك ثمن الفاتورة كاملًا عند استحقاقها.", "لا يوجد استثمار مضمون يتفوق على تكلفة الدين المرتفع، فسداده توفير مؤكد بمخاطرة أقل بكثير، وأقساطه تزاحم أي هدف ادخاري. ويُغرى المدينون كثيرًا بوعود الاستثمار، والترتيب الصحيح: الدين أولًا ثم الادخار ثم الاستثمار."),
        eg = TipWords("خلّص الديون الغالية قبل ما تستثمر", "قبل ما تحط فلوس في أي استثمار، سدّد الديون اللي تكلفتها عالية، وأولها رصيد البطاقة وخطط التقسيط الغالية. ادفع الحد الأدنى على كل دين، وأي فلوس زيادة حطها على الدين الأغلى. ومن هنا ورايح، ما تستخدمش بطاقة ائتمان غير لو هيكون معاك تمن الفاتورة كلها لما تيجي.", "مفيش استثمار مضمون يكسب أكتر من تكلفة الدين الغالي، فسداده توفير أكيد بمخاطرة أقل بكتير، وأقساطه بتنافس أي هدف ادخار. واللي عليه ديون بيتشد لوعود الاستثمار، والترتيب الصح: الدين، بعدين الادخار، بعدين الاستثمار."),
        source = TipSource("هيئة الأوراق المالية الأمريكية (موقع توعية المستثمر) — سدّد البطاقات الائتمانية والديون مرتفعة التكلفة", "https://www.investor.gov/introduction-investing/investing-basics/save-and-invest/pay-credit-cards-or-other-high-interest", "2026-10-16"),
